var GP = {'A+':4.0,'A':4.0,'A-':3.7,'B+':3.3,'B':3.0,'B-':2.7,'C+':2.3,'C':2.0,'C-':1.7,'D+':1.3,'D':1.0,'D-':0.7,'F':0.0};
function gradeToPoint(g){ var v=GP[String(g).trim().toUpperCase()]; return (v===undefined)?null:v; }
function gpa(courses){
  var pts=0, cr=0;
  for(var i=0;i<courses.length;i++){
    var p=gradeToPoint(courses[i].grade); if(p===null) return null;
    pts += p*courses[i].credit; cr += courses[i].credit;
  }
  return cr ? pts/cr : null;
}
var EXPORTS = { GP:GP, gradeToPoint:gradeToPoint, gpa:gpa };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.GpaForgePure = EXPORTS; }
